def bubble_fraction(stages: int, microbatches: int) -> float:
    """Idle fraction of a naive forward pipeline: (p - 1) / (m + p - 1), rounded to 4 decimals."""
    return round((stages - 1) / (microbatches + stages - 1), 4)

print(bubble_fraction(4, 4))
print(bubble_fraction(4, 16))
print(bubble_fraction(8, 32))
